import sys

def main():
    line = sys.stdin.readline()
    if not line:
        return
    parts = line.split()
    n = int(parts[0])
    k = int(parts[1])

    def ask(c):
        print(f"? {c}")
        sys.stdout.flush()
        resp = sys.stdin.readline().strip()
        if resp == 'E':
            sys.exit(0)
        return resp == 'Y'

    def reset():
        print("R")
        sys.stdout.flush()

    distinct_count = 0
    i = 0
    while i < n:
        reset()
        found_new = False
        j = i
        while j < n and j - i < k:
            if ask(j + 1):
                pass
            else:
                distinct_count += 1
                found_new = True
            j += 1

        if not found_new:
            break

        if j >= n:
            break

        step = k // 2
        while j < n:
            reset()
            block_found = False
            for t in range(i, min(i + k, j)):
                if ask(t + 1):
                    pass
                else:
                    block_found = True

            if not block_found:
                break

            new_block_start = j
            new_block_end = min(j + k, n)
            reset()
            block_has_new = False
            for t in range(new_block_start, new_block_end):
                if ask(t + 1):
                    pass
                else:block_has_new = True

            if block_has_new:
                distinct_count += 1
                j = new_block_end
            else:
                j += step
                if j > new_block_end:
                    j = new_block_end

        i = j

    print(f"! {distinct_count}")
    sys.stdout.flush()

if __name__ == "__main__":
    main()
